  const states={claims:{host:'claimRecords',table:'cc-claims-table',page:1,filters:{caseStatusKey:['open']},rows:[],view:[]},procurement:{host:'procurementContent',table:'cc-procurement-table',page:1,filters:{},rows:[],view:[]}};
  const mounted=new WeakSet();
