    if(button.dataset.ccReason!==undefined&&procurementDetail){const key=button.dataset.ccReason;procurementDetail.openReasons.has(key)?procurementDetail.openReasons.delete(key):procurementDetail.openReasons.add(key);showProcurementDetail(procurementDetail.supplier);Array.from(document.getElementById('ccProcurementDetail')?.querySelectorAll?.('[data-cc-reason]')||[]).find(el=>el.dataset.ccReason===key)?.focus();return;}
    if(button.dataset.ccReasonPage!==undefined&&procurementDetail){const key=button.dataset.ccReasonPage;procurementDetail.reasonPages.set(key,(procurementDetail.reasonPages.get(key)||1)+Number(button.dataset.ccStep));showProcurementDetail(procurementDetail.supplier);return;}
